with filtered_order_items as (select *, case when unit_price >= 380 then 'High' when unit_price >= 160 then 'Medium' else 'Low' end as unit_price_band from order_items where order_id in (21, 36) and unit_price < 240), summary as (select product_id, case when quantity >= 8 then 'high' when quantity >= 4 then 'mid' else 'low' end as quantity_bucket, round(stddev(quantity), 2) as stddev_quantity, round(avg(unit_price), 2) as avg_unit_price from filtered_order_items group by product_id, case when quantity >= 8 then 'high' when quantity >= 4 then 'mid' else 'low' end) select * from summary where stddev_quantity >= 66 order by avg_unit_price desc, product_id, quantity_bucket limit 10;
